schema = {'id': str, 'ladder_rank': int}
def validate(rec):
    return all(k in rec and isinstance(rec[k], t) for k, t in schema.items())
print('valid record:', validate({'id': 'x', 'ladder_rank': 2}))
print('invalid record:', validate({'id': 'x'}))

